async function generateSeedance({
  prompt,
  images,
  videos,
  audios,
  params: {
    seconds,
    size,
    resolution,
    ratio,
    generateAudio,
    watermark,
  },
  model,
  baseUrl,
  apiKey,
  request,
  poll,
  signal,
}) {
  const matched =
    /^bytedance\/(seedance-2\.0(?:-fast|-mini)?|seedance-2\.5)\/(text-to-video|image-to-video|reference-to-video)$/.exec(model);

  if (!matched) {
    throw new Error("请选择列表中的完整 Seedance 模型 ID");
  }

  const [, family, type] = matched;
  const is25 = family === "seedance-2.5";
  const hasMedia = images.length || videos.length || audios.length;

  // 按选中的模型检查输入，不自动切换模型。
  if (type === "text-to-video") {
    if (!prompt.trim()) {
      throw new Error("文生视频需要填写提示词");
    }
    if (hasMedia) {
      throw new Error(
        "当前选择的是文生视频模型；使用素材请切换图生或参考生视频模型"
      );
    }
  } else if (type === "image-to-video") {
    if (!images.length) {
      throw new Error("图生视频需要连接首帧图片");
    }
    if (images.length > 2 || videos.length || audios.length) {
      throw new Error(
        "图生视频使用首帧和可选尾帧；多图、视频或音频参考请使用 reference-to-video"
      );
    }
  } else {
    if (!hasMedia) {
      throw new Error(
        "参考生视频需要参考素材；只有提示词请使用 text-to-video"
      );
    }
    if (!is25 && !images.length && !videos.length) {
      throw new Error(
        "Seedance 2.0 系列的音频参考需要同时提供图片或视频"
      );
    }
  }

  // 使用完整 URL，避免项目额外追加 /v1。
  const root = new URL("/api/v1/model/", baseUrl).href;
  const headers = { Authorization: `Bearer ${apiKey}` };

  function errorText(value) {
    if (typeof value === "string") return value;
    return (
      value?.message ||
      value?.error?.message ||
      (typeof value?.error === "string" ? value.error : "")
    );
  }

  async function call(path, data) {
    signal?.throwIfAborted();

    let result;
    try {
      result = await request({
        method: data === undefined ? "get" : "post",
        url: root + path,
        headers:
          data === undefined || data instanceof FormData
            ? headers
            : { ...headers, "Content-Type": "application/json" },
        ...(data === undefined ? {} : { data }),
      });
    } catch (error) {
      if (signal?.aborted) throw error;
      throw new Error(errorText(error.response?.data) || error.message);
    }

    if (
      result?.code != null &&
      ![0, 200].includes(Number(result.code))
    ) {
      throw new Error(
        errorText(result) || `Atlas 返回错误码 ${result.code}`
      );
    }

    const value = result?.data ?? result;
    if (!value || typeof value !== "object") {
      throw new Error("Atlas 返回了无效响应");
    }

    return value;
  }

  async function uploadFiles(files) {
    const urls = [];

    for (const file of files) {
      const form = new FormData();
      form.append("file", file, file.name);

      const result = await call("uploadMedia", form);
      const url = result.download_url || result.url;

      if (typeof url !== "string" || !/^https?:\/\//i.test(url)) {
        throw new Error(`素材上传未返回有效地址：${file.name}`);
      }

      urls.push(url);
    }

    return urls;
  }

  const body = {
    model,
    prompt,
    duration: Number(seconds),
    resolution,
    ratio: size == null || ratio === "auto" ? "adaptive" : ratio,
    generate_audio: generateAudio,
    watermark,
    return_last_frame: false,
  };

  if (type === "image-to-video") {
    body.image = images[0];

    if (images[1]) {
      body.last_image = images[1];
    }

    // Seedance 2.5 图生视频只接受 adaptive。
    if (is25) {
      body.ratio = "adaptive";
    }
  } else if (type === "reference-to-video") {
    if (images.length) {
      body.reference_images = images;
    }

    if (videos.length) {
      body.reference_videos = await uploadFiles(videos);
    }

    if (audios.length) {
      body.reference_audios = await uploadFiles(audios);
    }

    if (is25) {
      body.omni_reference_task_type = "reference";
    }
  }

  if (is25) {
    body.output_format = "mp4";
  }

  const task = await call("generateVideo", body);

  if (!task.id) {
    throw new Error(
      errorText(task) ||
      "提交结果缺少任务 ID；请先到 Atlas 后台确认，避免重复提交"
    );
  }

  console.info("[Atlas Seedance] 模型:", model, "任务 ID:", task.id);

  try {
    // 沿用项目默认的查询间隔和轮询期限。
    return await poll(
      async () => {
        const state = await call(
          `prediction/${encodeURIComponent(task.id)}`
        );

        if (["failed", "timeout"].includes(state.status)) {
          throw new Error(
            errorText(state.error) ||
            errorText(state) ||
            `生成失败：${state.status}`
          );
        }

        if (!["completed", "succeeded"].includes(state.status)) {
          return null;
        }

        const url = state.outputs?.[0];
        if (typeof url !== "string" || !/^https?:\/\//i.test(url)) {
          throw new Error("任务完成，但未返回视频地址");
        }

        return { url };
      },
      (result) => result
    );
  } catch (error) {
    if (signal?.aborted) throw error;
    throw new Error(
      `${error.message}；Atlas 任务 ID：${task.id}。` +
      "查询中断不代表云端任务已取消，请先查看该任务结果。"
    );
  }
}

return await generateSeedance({
  prompt,
  images,
  videos,
  audios,
  params,
  model,
  baseUrl,
  apiKey,
  request,
  poll,
  signal,
});

